sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var producerSysId = gs.getSessionValue('record_producer_sys_id');
	gs.addInfoMessage('producer is: ' + producerSysId);
    if (producerSysId == '8ed3eae73b9d125013b9202a85e45ab3') {
        var softwareSupportLvl2 = 'AAP Support SW Lvl 2';
        var hardwareSupportLvl2 = 'AAP Support HW Lvl 2';
        var softwareSupportLvl1 = 'AAP Support SW Lvl 1';
        var hardwareSupportLvl1 = 'AAP Support HW Lvl 1';
        //e9595ef7eb1dd250f5c4f897cad0cdfc
        var groupName;

        var priority = parseInt(current.getValue('priority'));
        gs.info('AAP priority: ' + priority + '  ' + typeof priority);
        gs.addInfoMessage('priority is: ' + priority);
        var category = current.category;

        switch (priority) {
            case 1:
                gs.info('AAP priority: ' + priority + '  ' + typeof priority);
                if (category == 'software') {
                    groupName = softwareSupportLvl2;
                } else if (category == 'hardware') {
                    groupName = hardwareSupportLvl2;
                }
                break;
            case 2:
                gs.info('AAP priority: ' + priority + '  ' + typeof priority);
                if (category == 'software') {
                    groupName = softwareSupportLvl2;
                } else if (category == 'hardware') {
                    groupName = hardwareSupportLvl2;
                }
                break;
            case 3:
                gs.info('AAP priority: ' + priority + '  ' + typeof priority);
                if (category == 'software') {
                    groupName = softwareSupportLvl1;
                } else if (category == 'hardware') {
                    groupName = hardwareSupportLvl1;
                }
                break;
            case 4:
                gs.info('AAP priority: ' + priority + '  ' + typeof priority);
                if (category == 'software') {
                    groupName = softwareSupportLvl1;
                } else if (category == 'hardware') {
                    groupName = hardwareSupportLvl1;
                }
                break;
            case 5:
                gs.info('AAP priority: ' + priority + '  ' + typeof priority);
                if (category == 'software') {
                    groupName = softwareSupportLvl1;
                } else if (category == 'hardware') {
                    groupName = hardwareSupportLvl1;
                }
                break;
        }

        gs.info('completed');
        gs.info('groupName is: ' + groupName);
        //current.assignment_group = groupName;

        var groupGR = new GlideRecord('sys_user_group');
        groupGR.addQuery('name', groupName);
        groupGR.query();
        if (groupGR.next()) {
            gs.info('ist in if: ' + groupGR.sys_id);
            current.setValue('assignment_group', groupGR.sys_id);
            current.update();
        }
    }

})(current, previous);
